UPDATE public.recipes SET calories = 1450, ready_in_minutes = 60, difficulty = 'easy', instructions = ARRAY['Cuci ikan tuna sampai bersih, lalu beri perasan jeruk lemon dan garam. Aduk rata dan diamkan sekitar 30 menit agar bau amis hilang.', 'Sementara itu, haluskan bawang merah, bawang putih, cabai merah keriting, kemiri, jahe, dan kunyit.', 'Tumis bumbu halus dengan sedikit minyak hingga harum. Tambahkan serai, lengkuas, daun jeruk, dan daun salam. Tumis lagi sampai bumbu benar-benar matang dan wangi, lalu tuangkan air secukupnya.', 'Setelah air mendidih, masukkan potongan ikan tuna, tomat yang sudah dipotong kecil, dan cabai rawit merah.', 'Masak hingga ikan matang dan kuahnya sedikit menyusut. Bumbui dengan garam dan gula sesuai selera, aduk rata.', 'Tuang santan instan, aduk perlahan terus-menerus hingga mendidih agar santan tidak pecah.', 'Cicipi kuahnya, lalu masukkan potongan kacang panjang dan daun bawang. Tutup panci dan masak sebentar sampai kacang panjang matang.', 'Jika rasa sudah pas, matikan api. Pindahkan gulai ikan tuna ke wadah saji dan hidangkan.'] WHERE id = 47;
